package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"time"
)

// Kinds of transcript entries.
const (
	kindUser       = "user"
	kindAssistant  = "assistant"
	kindThinking   = "thinking"
	kindToolUse    = "tool_use"
	kindToolResult = "tool_result"
)

type entry struct {
	kind string
	text string
	ts   time.Time
}

// item is one browsable file: a .jsonl session transcript or a .md daily log.
type item struct {
	path   string
	isMD   bool
	title  string
	ts     time.Time
	count  int    // messages (jsonl) or log entries (md)
	search string // lowercased searchable text
}

type rawRec struct {
	Type        string `json:"type"`
	IsSidechain bool   `json:"isSidechain"`
	IsMeta      bool   `json:"isMeta"`
	Timestamp   string `json:"timestamp"`
	Message     *struct {
		Role    string          `json:"role"`
		Content json.RawMessage `json:"content"`
	} `json:"message"`
}

type block struct {
	Type     string          `json:"type"`
	Text     string          `json:"text"`
	Thinking string          `json:"thinking"`
	Name     string          `json:"name"`
	Input    json.RawMessage `json:"input"`
	Content  json.RawMessage `json:"content"`
}

var (
	reminderRe = regexp.MustCompile(`(?s)<system-reminder>.*?</system-reminder>`)
	noisePrefs = []string{"<local-command", "<command-name>", "<command-message>", "<bash-"}
)

func scanLines(path string, fn func([]byte)) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	defer f.Close()
	r := bufio.NewReaderSize(f, 1<<20)
	for {
		line, err := r.ReadBytes('\n')
		if len(strings.TrimSpace(string(line))) > 0 {
			fn(line)
		}
		if err != nil {
			return nil
		}
	}
}

// parseSession converts a transcript into displayable entries.
func parseSession(path string) ([]entry, error) {
	var out []entry
	err := scanLines(path, func(line []byte) {
		var r rawRec
		if json.Unmarshal(line, &r) != nil || r.Message == nil || r.IsSidechain || r.IsMeta {
			return
		}
		if r.Type != "user" && r.Type != "assistant" {
			return
		}
		ts, _ := time.Parse(time.RFC3339Nano, r.Timestamp)
		var s string
		if json.Unmarshal(r.Message.Content, &s) == nil {
			if t := cleanUser(s); t != "" && r.Type == "user" {
				out = append(out, entry{kindUser, t, ts})
			} else if t != "" {
				out = append(out, entry{kindAssistant, t, ts})
			}
			return
		}
		var blocks []block
		if json.Unmarshal(r.Message.Content, &blocks) != nil {
			return
		}
		for _, b := range blocks {
			switch b.Type {
			case "text":
				if r.Type == "user" {
					if t := cleanUser(b.Text); t != "" {
						out = append(out, entry{kindUser, t, ts})
					}
				} else if t := strings.TrimSpace(b.Text); t != "" {
					out = append(out, entry{kindAssistant, t, ts})
				}
			case "thinking":
				if t := strings.TrimSpace(b.Thinking); t != "" {
					out = append(out, entry{kindThinking, t, ts})
				}
			case "tool_use":
				out = append(out, entry{kindToolUse, fmt.Sprintf("%s %s", b.Name, compact(b.Input)), ts})
			case "tool_result":
				out = append(out, entry{kindToolResult, resultText(b.Content), ts})
			}
		}
	})
	return out, err
}

func cleanUser(s string) string {
	s = strings.TrimSpace(reminderRe.ReplaceAllString(s, ""))
	for _, p := range noisePrefs {
		if strings.HasPrefix(s, p) {
			return ""
		}
	}
	return s
}

func compact(raw json.RawMessage) string {
	var m map[string]any
	if json.Unmarshal(raw, &m) != nil {
		return string(raw)
	}
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var parts []string
	for _, k := range keys {
		v := fmt.Sprint(m[k])
		v = strings.Join(strings.Fields(v), " ")
		if len(v) > 120 {
			v = v[:120] + "…"
		}
		parts = append(parts, k+"="+v)
	}
	return strings.Join(parts, " ")
}

func resultText(raw json.RawMessage) string {
	var s string
	if json.Unmarshal(raw, &s) == nil {
		return strings.TrimSpace(s)
	}
	var bs []block
	if json.Unmarshal(raw, &bs) == nil {
		var sb strings.Builder
		for _, b := range bs {
			sb.WriteString(b.Text)
		}
		return strings.TrimSpace(sb.String())
	}
	return ""
}

// loadItems scans dir for session transcripts and daily markdown logs.
func loadItems(dir string) ([]item, error) {
	files, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	var items []item
	for _, f := range files {
		if f.IsDir() {
			continue
		}
		p := filepath.Join(dir, f.Name())
		info, _ := f.Info()
		switch strings.ToLower(filepath.Ext(f.Name())) {
		case ".jsonl":
			entries, _ := parseSession(p)
			it := item{path: p, ts: info.ModTime(), title: "(no prompts)"}
			var sb strings.Builder
			first := true
			for _, e := range entries {
				if e.kind == kindUser || e.kind == kindAssistant {
					it.count++
					sb.WriteString(strings.ToLower(e.text))
					sb.WriteByte('\n')
				}
				if first && !e.ts.IsZero() {
					it.ts, first = e.ts, false
				}
				if e.kind == kindUser && it.title == "(no prompts)" {
					it.title = oneLine(e.text)
				}
			}
			it.search = strings.ToLower(it.title) + "\n" + sb.String()
			items = append(items, it)
		case ".md":
			b, err := os.ReadFile(p)
			if err != nil {
				continue
			}
			txt := string(b)
			it := item{path: p, isMD: true, ts: info.ModTime(), search: strings.ToLower(txt),
				title: "Daily log " + strings.TrimSuffix(f.Name(), filepath.Ext(f.Name()))}
			if t, err := time.ParseInLocation("2006-01-02", strings.TrimSuffix(f.Name(), ".md"), time.Local); err == nil {
				it.ts = t
			}
			for _, l := range strings.Split(txt, "\n") {
				if strings.HasPrefix(l, "## ") {
					it.count++
				}
			}
			items = append(items, it)
		}
	}
	sort.Slice(items, func(i, j int) bool { return items[i].ts.After(items[j].ts) })
	return items, nil
}

func oneLine(s string) string {
	return strings.Join(strings.Fields(s), " ")
}
EOF
cat > main.go <<'EOF'
// chat-browser: a terminal UI for browsing Claude Code chat history.
//
// Usage: chat-browser [dir]    (default dir: ./chat-history, else ../chat-history)
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/charmbracelet/bubbles/textinput"
	"github.com/charmbracelet/bubbles/viewport"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/charmbracelet/x/ansi"
)

var (
	titleSt  = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("15")).Background(lipgloss.Color("62")).Padding(0, 1)
	helpSt   = lipgloss.NewStyle().Foreground(lipgloss.Color("241"))
	selSt    = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("15")).Background(lipgloss.Color("237"))
	dimSt    = lipgloss.NewStyle().Foreground(lipgloss.Color("244"))
	userSt   = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("39"))
	asstSt   = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("213"))
	toolSt   = lipgloss.NewStyle().Foreground(lipgloss.Color("178"))
	thinkSt  = lipgloss.NewStyle().Italic(true).Foreground(lipgloss.Color("243"))
	mdHeadSt = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("42"))
)

type mode int

const (
	modeList mode = iota
	modeView
)

type model struct {
	dir           string
	items         []item
	shown         []int // indexes into items after filtering
	cursor, top   int
	filter        textinput.Model
	filtering     bool
	mode          mode
	vp            viewport.Model
	cur           *item
	entries       []entry
	showTools     bool
	showThinking  bool
	promptLines   []int
	w, h          int
	err           error
}

func newModel(dir string) model {
	ti := textinput.New()
	ti.Prompt = "/ "
	ti.Placeholder = "search sessions…"
	m := model{dir: dir, filter: ti, vp: viewport.New(80, 20)}
	m.items, m.err = loadItems(dir)
	m.applyFilter()
	return m
}

func (m *model) applyFilter() {
	q := strings.ToLower(strings.TrimSpace(m.filter.Value()))
	m.shown = m.shown[:0]
	for i, it := range m.items {
		if q == "" || strings.Contains(it.search, q) {
			m.shown = append(m.shown, i)
		}
	}
	if m.cursor >= len(m.shown) {
		m.cursor = max(0, len(m.shown)-1)
	}
	m.clampTop()
}

func (m model) listHeight() int { return max(1, m.h-4) }

func (m *model) clampTop() {
	lh := m.listHeight()
	if m.cursor < m.top {
		m.top = m.cursor
	}
	if m.cursor >= m.top+lh {
		m.top = m.cursor - lh + 1
	}
	if m.top < 0 {
		m.top = 0
	}
}

func (m model) Init() tea.Cmd { return nil }

func (m *model) open() {
	if len(m.shown) == 0 {
		return
	}
	it := m.items[m.shown[m.cursor]]
	m.cur = &it
	m.entries = nil
	if !it.isMD {
		m.entries, _ = parseSession(it.path)
	}
	m.mode = modeView
	m.render()
	m.vp.GotoTop()
}

// render rebuilds the viewport content for the open item.
func (m *model) render() {
	w := max(20, m.w-2)
	var sb strings.Builder
	line := 0
	add := func(s string) {
		sb.WriteString(s)
		sb.WriteByte('\n')
		line += strings.Count(s, "\n") + 1
	}
	m.promptLines = nil
	if m.cur.isMD {
		b, err := os.ReadFile(m.cur.path)
		if err != nil {
			add(err.Error())
		}
		for _, l := range strings.Split(string(b), "\n") {
			l = strings.TrimRight(l, "\r")
			if strings.HasPrefix(l, "#") {
				l = mdHeadSt.Render(l)
			}
			add(lipgloss.NewStyle().Width(w).Render(l))
		}
		m.vp.SetContent(sb.String())
		return
	}
	body := lipgloss.NewStyle().Width(w - 2)
	for _, e := range m.entries {
		ts := ""
		if !e.ts.IsZero() {
			ts = dimSt.Render("  " + e.ts.Local().Format("15:04:05"))
		}
		switch e.kind {
		case kindUser:
			m.promptLines = append(m.promptLines, line)
			add(userSt.Render("▌ You") + ts)
			add(indent(body.Render(e.text)))
			add("")
		case kindAssistant:
			add(asstSt.Render("▌ Claude") + ts)
			add(indent(body.Render(e.text)))
			add("")
		case kindThinking:
			if m.showThinking {
				add(indent(thinkSt.Render(body.Render("thinking: " + e.text))))
				add("")
			}
		case kindToolUse:
			if m.showTools {
				add(indent(toolSt.Render(ansi.Truncate("⚙ "+e.text, w-2, "…"))))
			}
		case kindToolResult:
			if m.showTools {
				t := oneLine(e.text)
				add(indent(dimSt.Render(ansi.Truncate("  ↳ "+t, w-2, "…"))))
				add("")
			}
		}
	}
	if len(m.entries) == 0 {
		add(dimSt.Render("(no messages)"))
	}
	m.vp.SetContent(sb.String())
}

func indent(s string) string {
	return "  " + strings.ReplaceAll(strings.TrimRight(s, "\n"), "\n", "\n  ")
}

func (m model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.w, m.h = msg.Width, msg.Height
		m.vp.Width, m.vp.Height = msg.Width, max(1, msg.Height-3)
		m.filter.Width = max(10, msg.Width-6)
		m.clampTop()
		if m.mode == modeView {
			y := m.vp.YOffset
			m.render()
			m.vp.SetYOffset(y)
		}
		return m, nil
	case tea.KeyMsg:
		if m.mode == modeList {
			return m.updateList(msg)
		}
		return m.updateView(msg)
	}
	return m, nil
}

func (m model) updateList(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	if m.filtering {
		switch msg.String() {
		case "enter":
			m.filtering = false
			m.filter.Blur()
			return m, nil
		case "esc":
			m.filtering = false
			m.filter.Blur()
			m.filter.SetValue("")
			m.applyFilter()
			return m, nil
		}
		var cmd tea.Cmd
		m.filter, cmd = m.filter.Update(msg)
		m.applyFilter()
		return m, cmd
	}
	n := len(m.shown)
	switch msg.String() {
	case "q", "ctrl+c":
		return m, tea.Quit
	case "up", "k":
		m.cursor = max(0, m.cursor-1)
	case "down", "j":
		m.cursor = min(max(0, n-1), m.cursor+1)
	case "pgup":
		m.cursor = max(0, m.cursor-m.listHeight())
	case "pgdown":
		m.cursor = min(max(0, n-1), m.cursor+m.listHeight())
	case "home", "g":
		m.cursor = 0
	case "end", "G":
		m.cursor = max(0, n-1)
	case "/":
		m.filtering = true
		return m, m.filter.Focus()
	case "esc":
		m.filter.SetValue("")
		m.applyFilter()
	case "r":
		m.items, m.err = loadItems(m.dir)
		m.applyFilter()
	case "enter", "right", "l":
		m.open()
	}
	m.clampTop()
	return m, nil
}

func (m model) updateView(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "ctrl+c":
		return m, tea.Quit
	case "q", "esc", "backspace", "left", "h":
		m.mode = modeList
		return m, nil
	case "t":
		m.showTools = !m.showTools
		m.render()
		return m, nil
	case "T":
		m.showThinking = !m.showThinking
		m.render()
		return m, nil
	case "n":
		for _, l := range m.promptLines {
			if l > m.vp.YOffset {
				m.vp.SetYOffset(l)
				break
			}
		}
		return m, nil
	case "p":
		for i := len(m.promptLines) - 1; i >= 0; i-- {
			if m.promptLines[i] < m.vp.YOffset {
				m.vp.SetYOffset(m.promptLines[i])
				break
			}
		}
		return m, nil
	case "g", "home":
		m.vp.GotoTop()
		return m, nil
	case "G", "end":
		m.vp.GotoBottom()
		return m, nil
	case "j":
		m.vp.LineDown(1)
		return m, nil
	case "k":
		m.vp.LineUp(1)
		return m, nil
	}
	var cmd tea.Cmd
	m.vp, cmd = m.vp.Update(msg)
	return m, cmd
}

func (m model) View() string {
	if m.w == 0 {
		return "loading…"
	}
	if m.mode == modeView {
		return m.viewReader()
	}
	var sb strings.Builder
	head := fmt.Sprintf("Chat History · %s · %d/%d", m.dir, len(m.shown), len(m.items))
	sb.WriteString(titleSt.Render(ansi.Truncate(head, m.w-2, "…")) + "\n")
	if m.filtering || m.filter.Value() != "" {
		sb.WriteString(m.filter.View() + "\n")
	} else {
		sb.WriteString(helpSt.Render("press / to search") + "\n")
	}
	if m.err != nil {
		sb.WriteString("error: " + m.err.Error() + "\n")
	}
	lh := m.listHeight()
	for row := 0; row < lh; row++ {
		i := m.top + row
		if i >= len(m.shown) {
			sb.WriteString("\n")
			continue
		}
		it := m.items[m.shown[i]]
		kind, unit := "chat", "msgs"
		if it.isMD {
			kind, unit = "log ", "entries"
		}
		s := fmt.Sprintf(" %s  %s  %3d %-7s %s", it.ts.Local().Format("2006-01-02 15:04"), kind, it.count, unit, it.title)
		s = ansi.Truncate(s, m.w, "…")
		if i == m.cursor {
			s = selSt.Width(m.w).Render(s)
		}
		sb.WriteString(s + "\n")
	}
	sb.WriteString(helpSt.Render("↑/↓ move · enter open · / search · r reload · q quit"))
	return sb.String()
}

func (m model) viewReader() string {
	pct := int(m.vp.ScrollPercent() * 100)
	head := fmt.Sprintf("%s · %s", m.cur.ts.Local().Format("2006-01-02 15:04"), m.cur.title)
	foot := fmt.Sprintf("%3d%% · ↑/↓ PgUp/PgDn scroll · n/p next/prev prompt · t tools[%s] · T thinking[%s] · esc back",
		pct, onOff(m.showTools), onOff(m.showThinking))
	return titleSt.Render(ansi.Truncate(head, m.w-2, "…")) + "\n" + m.vp.View() + "\n" +
		helpSt.Render(ansi.Truncate(foot, m.w, "…"))
}

func onOff(b bool) string {
	if b {
		return "on"
	}
	return "off"
}

func findDir() string {
	if len(os.Args) > 1 {
		return os.Args[1]
	}
	for _, c := range []string{"chat-history", filepath.Join("..", "chat-history")} {
		if st, err := os.Stat(c); err == nil && st.IsDir() {
			return c
		}
	}
	return "chat-history"
}

func main() {
	p := tea.NewProgram(newModel(findDir()), tea.WithAltScreen())
	if _, err := p.Run(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}
