package main

import (
	"fmt"
	"os"
	"path/filepath"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/spf13/cobra"
)

var version = "dev"

// defaultDirs are searched, in order, in the current working directory.
var defaultDirs = []string{".chat-history", "chat-history"}

type options struct {
	dir string
}

// resolveDir returns the history directory: an explicit path if given,
// otherwise the first of defaultDirs that exists under the current directory.
func resolveDir(explicit string) (string, error) {
	if explicit != "" {
		st, err := os.Stat(explicit)
		if err != nil {
			return "", err
		}
		if !st.IsDir() {
			return "", fmt.Errorf("%s is not a directory", explicit)
		}
		return explicit, nil
	}
	for _, c := range defaultDirs {
		if st, err := os.Stat(c); err == nil && st.IsDir() {
			return c, nil
		}
	}
	return "", fmt.Errorf("no %s or %s folder in %s (use --dir to specify one)",
		defaultDirs[0], defaultDirs[1], mustGetwd())
}

func mustGetwd() string {
	wd, err := os.Getwd()
	if err != nil {
		return "."
	}
	return wd
}

func newRootCmd() *cobra.Command {
	var opts options
	cmd := &cobra.Command{
		Use:   "chat-browser [dir]",
		Short: "Browse Claude Code chat history in a terminal UI",
		Long: `Browse Claude Code chat history in a terminal UI.

Without arguments, looks for .chat-history or chat-history in the current
directory. Pass a directory as an argument or with --dir to use another one.`,
		Args:          cobra.MaximumNArgs(1),
		Version:       version,
		SilenceUsage:  true,
		SilenceErrors: true,
		RunE: func(cmd *cobra.Command, args []string) error {
			path := opts.dir
			if len(args) == 1 {
				if path != "" && path != args[0] {
					return fmt.Errorf("both --dir and a positional path were given")
				}
				path = args[0]
			}
			dir, err := resolveDir(path)
			if err != nil {
				return err
			}
			abs, err := filepath.Abs(dir)
			if err != nil {
				abs = dir
			}
			p := tea.NewProgram(newModel(abs), tea.WithAltScreen())
			_, err = p.Run()
			return err
		},
	}
	cmd.Flags().StringVarP(&opts.dir, "dir", "d", "", "path to the chat history directory")
	return cmd
}

func main() {
	if err := newRootCmd().Execute(); err != nil {
		fmt.Fprintln(os.Stderr, "chat-browser:", err)
		os.Exit(1)
	}
}

